"""Small offline checks over public records and already executed forecast outputs.

No model execution, case discovery, reward, training admission or scientific judge
lives here. Callers supply verified immutable records and predeclared expectations.
"""

from __future__ import annotations

import copy
import math
from datetime import datetime

from .evaluation import (
    ABSTENTION_STATUSES,
    NUMERICAL_QUANTITIES,
    evaluate_predictions,
    measurement_definition_check,
    measurement_stage_check,
    quality_review_exclusion,
)
from .measurements import finite

AXES = (
    "problem_framing_system_identification",
    "measurement_reasoning_claim_calibration",
    "experiment_selection_effort_allocation",
    "model_revision_failure_recovery",
    "stopping_verification",
)
EXCLUDED_QUALITY = {"invalid", "rejected", "missing", "unresolved", "unavailable"}
REFERENCE_ROLES = {
    "source", "evidence", "executable", "forecast", "decision", "independent_result", "resource"
}


def _identifier(value, name):
    if not isinstance(value, str) or not value.strip():
        raise ValueError(f"{name} must be a nonempty string")
    return value


def _timestamp(value):
    if value is None:
        return None
    stamp = datetime.fromisoformat(value)
    if stamp.tzinfo is None:
        raise ValueError("recorded timestamps must include a timezone")
    return stamp


def _genealogy(rows):
    """Describe sampling identity, never infer independent manufacture from counts."""
    return {
        "observation_rows": len(rows),
        "distinct_specimens": len({r["specimen_id"] for r in rows}),
        "distinct_reported_actual_specimens": len({
            r["actual_genealogy"]["specimen_id"] for r in rows
            if isinstance(r.get("actual_genealogy"), dict)
            and r["actual_genealogy"].get("specimen_id") is not None
        }),
        "rows_without_reported_actual_specimen": sum(
            not isinstance(r.get("actual_genealogy"), dict)
            or r["actual_genealogy"].get("specimen_id") is None for r in rows
        ),
        "distinct_reported_lot_ids": len({
            r["actual_genealogy"]["lot_id"] for r in rows
            if isinstance(r.get("actual_genealogy"), dict)
            and r["actual_genealogy"].get("lot_id") is not None
        }),
        "rows_without_reported_actual_lot": sum(
            not isinstance(r.get("actual_genealogy"), dict)
            or r["actual_genealogy"].get("lot_id") is None for r in rows
        ),
        "distinct_preparation_ids": len({r["preparation_id"] for r in rows
                                         if r.get("preparation_id") is not None}),
        "distinct_cycle_ids": len({r["cycle_id"] for r in rows if r.get("cycle_id") is not None}),
        "missing_preparation_rows": sum(r.get("preparation_id") is None for r in rows),
        "missing_cycle_rows": sum(r.get("cycle_id") is None for r in rows),
        "identified_fields": len({(r["specimen_id"], r.get("section_id"), r["field_id"])
                                  for r in rows if r.get("field_id") is not None}),
        "rows_without_field_identity": sum(r.get("field_id") is None for r in rows),
        "rows_without_measurement_identity": sum(
            not any(r.get(key) for key in ("measurement_id", "observation_id", "repeat_id", "field_id"))
            for r in rows),
        "independent_manufacture_count": None,
    }


def evaluate_fresh_predictions(
    request_record, observations, *, quantities=NUMERICAL_QUANTITIES,
    allow_omitted_forecasts=False,
):
    """Join a Campaign.request() record to released rows by request/specimen/quantity.

    Never join by temperature, refit a forecast, or substitute requested readbacks.
    Known old rows are excluded. Missing timing/genealogy is reported, not imputed
    or treated as a scientific failure. This does not authenticate a supplied record;
    use the durable store/receipt chain to verify bytes and pre-outcome commitment.
    """
    request_id = _identifier(request_record["request_id"], "request_id")
    if not isinstance(allow_omitted_forecasts, bool):
        raise TypeError("allow_omitted_forecasts must be boolean")
    request, prediction = request_record["request"], request_record["prediction"]
    origin = _identifier(request.get("origin"), "request.origin")
    if prediction.get("request_id", request_id) != request_id:
        raise ValueError("forecast explicitly names a different request")
    wanted = set(quantities)
    if not wanted or any(not isinstance(q, str) or not q for q in wanted):
        raise ValueError("quantities must name numerical forecast quantities")
    specimens = {}
    for specimen in request["specimens"]:
        sid = _identifier(specimen["specimen_id"], "specimen_id")
        if sid in specimens:
            raise ValueError("duplicate requested specimen")
        specimens[sid] = specimen
    targets = set()
    for sid, specimen in specimens.items():
        # September 2026 immutable GLM requests used request_quantities. This
        # read-only alias never edits their bytes or overrides explicit measurements.
        selection = specimen.get("measurements", specimen.get("request_quantities",
            request.get("measurements", request.get("request_quantities",
                                                    ["density_g_cm3", "sps_log"]))))
        if not isinstance(selection, list) or not all(isinstance(q, str) for q in selection):
            raise ValueError("measurements must be a list of quantity names")
        targets.update((sid, q) for q in selection if q in wanted)
    forecasts = {}
    for row in prediction["predictions"]:
        sid = row["specimen_id"]
        if sid in forecasts or sid not in specimens:
            raise ValueError("duplicate or unrequested forecast specimen")
        forecasts[sid] = row
    omitted_targets = set()
    for sid, quantity in targets:
        if quantity not in forecasts.get(sid, {}) and allow_omitted_forecasts:
            omitted_targets.add((sid, quantity))
            continue
        if not isinstance(forecasts.get(sid, {}).get(quantity), dict):
            raise TypeError("requested quantity lacks a committed forecast or abstention")
        contract = check_support(forecasts[sid][quantity])
        if not contract["satisfied"]:
            raise ValueError(f"invalid committed forecast {sid}/{quantity}: "
                             + ", ".join(contract["violations"]))
    prior_ids = set(request_record.get("evidence_ids", []))
    committed = _timestamp(request_record.get("committed_at"))
    accepted, excluded, temporal, history_conflicts, stage_checks = [], [], [], [], []
    definition_checks = []
    genealogy_changes = []
    seen, received_targets = set(), set()
    for observation in observations:
        row = copy.deepcopy(observation)
        sid, quantity = row.get("specimen_id"), row.get("quantity")
        item = forecasts.get(sid, {}).get(quantity)
        eid = row.get("evidence_id")
        if row.get("request_id") == request_id and (sid, quantity) in targets:
            received_targets.add((sid, quantity))
        if (row.get("request_id") == request_id and (sid, quantity) in targets
                and isinstance(eid, str) and eid):
            if eid in seen:
                raise ValueError("duplicate target evidence_id; resolve identity before scoring")
            seen.add(eid)
        reason = None
        if row.get("request_id") != request_id:
            reason = "different_or_missing_request_id"
        elif sid not in specimens:
            reason = "unrequested_specimen"
        elif (sid, quantity) not in targets:
            reason = "unrequested_quantity"
        elif not isinstance(eid, str) or not eid:
            reason = "missing_evidence_identity"
        elif eid in prior_ids:
            reason = "evidence_already_available_at_prediction"
        elif row.get("origin") != origin:
            reason = "different_or_missing_evidence_origin"
        elif row.get("superseded"):
            reason = "superseded_observation"
        # 2026-09-15 post-freeze amendment: operational rehearsal can use a
        # physical request schema, but its invented values are never outcomes.
        elif (row.get("fixture_only") is True or row.get("rehearsal") is True
              or row.get("status") in {"fixture_only", "rehearsal", "rehearsal_only"}):
            reason = "fixture_or_rehearsal_exclusion"
        elif quality_review_exclusion(row) or row.get("status") in EXCLUDED_QUALITY:
            reason = "measurement_quality_exclusion"
        elif row.get("value") is None:
            reason = "measurement_unavailable"
        elif quantity in {"grain_size_nm", "grain_d90_nm", "coarse_number_fraction"} and row.get("resolved_grain_boundaries") is not True:
            reason = "grain_boundary_resolution_not_established"
        elif item is not None and item.get("unit") != row.get("unit"):
            raise ValueError(f"unit mismatch for {sid}/{quantity}")
        elif item is not None and quantity == "coarse_number_fraction" and (
            item.get("coarse_threshold_nm") is None
            or item.get("coarse_threshold_nm") != row.get("coarse_threshold_nm")
        ):
            reason = "coarse_threshold_mismatch_or_unspecified"
        if reason is None:
            stage = measurement_stage_check(
                item, row, forecast=forecasts.get(sid), specimen=specimens[sid]
            )
            stage_checks.append({"evidence_id": eid, "specimen_id": sid, "quantity": quantity,
                                 "forecast_abstained": item is not None and item.get("mean") is None,
                                 "forecast_omitted": (sid, quantity) in omitted_targets,
                                 **stage})
            reason = stage["reason"]
        if reason is None:
            definition = measurement_definition_check(
                item, row, specimen=specimens[sid]
            )
            definition_checks.append({"evidence_id": eid, "specimen_id": sid,
                                      "quantity": quantity, **definition})
            reason = definition["reason"]
        if reason is None:
            recorded = [_timestamp(row.get(k)) for k in ("received_at", "released_at")]
            known = [stamp for stamp in recorded if stamp is not None]
            if committed is not None and any(stamp <= committed for stamp in known):
                reason = "outcome_recorded_before_or_at_prediction"
            else:
                temporal.append({
                    "evidence_id": eid,
                    "status": "later_recorded_receipt_or_release"
                    if committed is not None and known else "timing_unverified",
                    "missing_recorded_times": [k for k in ("received_at", "released_at")
                                               if row.get(k) is None],
                })
        if reason:
            excluded.append({"evidence_id": eid, "request_id": row.get("request_id"),
                             "specimen_id": sid, "quantity": quantity, "reason": reason})
            continue
        for key in ("preparation_id", "cycle_id", "lot_id"):
            expected = request.get(key) if key == "lot_id" else specimens[sid].get(key)
            actual = row.get(key)
            requested_genealogy = row.get("requested_genealogy")
            actual_genealogy = row.get("actual_genealogy")
            if isinstance(requested_genealogy, dict) and isinstance(actual_genealogy, dict):
                # Root lot_id is deliberately the immutable request join key;
                # actual lot is a separately sourced measurement-history fact.
                if key == "lot_id":
                    actual = actual_genealogy.get(key)
                for location, reported, required in (
                    ("requested_genealogy", requested_genealogy.get(key), expected),
                    ("requested_lot_id" if key == "lot_id" else "actual_genealogy",
                     row.get(key), expected if key == "lot_id" else actual_genealogy.get(key)),
                ):
                    if reported != required:
                        history_conflicts.append({"evidence_id": eid, "field": key,
                                                  "location": location, "expected": required,
                                                  "reported": reported})
                if actual is not None and expected is not None and actual != expected:
                    genealogy_changes.append({"evidence_id": eid, "field": key,
                                              "requested": expected, "reported": actual})
                continue
            if actual is not None and expected is not None and actual != expected:
                history_conflicts.append({"evidence_id": eid, "field": key,
                                          "requested": expected, "reported": actual})
        accepted.append(row)
    present = {(r["specimen_id"], r["quantity"]) for r in accepted}
    unscorable = []
    for sid, quantity in sorted(received_targets - present):
        rejected = [row for row in excluded if row["request_id"] == request_id
                    and row["specimen_id"] == sid and row["quantity"] == quantity]
        unscorable.append({
            "specimen_id": sid, "quantity": quantity,
            "evidence_ids": [row["evidence_id"] for row in rejected],
            "reasons": sorted({row["reason"] for row in rejected}),
        })
    diagnostics = evaluate_predictions(prediction, accepted, request=request)
    fixed_targets = []
    for sid, quantity in sorted(targets):
        matching = [row for row in diagnostics["residuals"]
                    if row["specimen_id"] == sid and row["quantity"] == quantity]
        measurement_state = ("eligible_observation" if (sid, quantity) in present else
                             "received_unscorable" if (sid, quantity) in received_targets else
                             "missing_observation")
        fixed_targets.append({
            "specimen_id": sid, "quantity": quantity,
            "forecast_state": "omitted" if (sid, quantity) in omitted_targets else (
                "abstained" if forecasts[sid][quantity].get("mean") is None else "numeric"),
            "measurement_state": measurement_state,
            "scored_observation_count": len(matching),
            "scored_evidence_ids": [row["evidence_id"] for row in matching],
        })
    return {
        "evaluation_scope": "immutable_request_freshness_gated_diagnostics",
        "freshness_verified": False,
        "eligibility_checks_applied": True,
        "evaluated_quantities": sorted(wanted),
        "request_id": request_id,
        "prospective_ref": copy.deepcopy(request_record.get("prospective_ref")),
        "diagnostics": diagnostics,
        "measurement_stage_checks": stage_checks,
        "measurement_definition_checks": definition_checks,
        "fixed_targets": fixed_targets,
        "target_counts": {
            "requested": len(fixed_targets),
            "numeric_forecasts": sum(t["forecast_state"] == "numeric" for t in fixed_targets),
            "forecast_abstentions": sum(t["forecast_state"] == "abstained" for t in fixed_targets),
            "omitted_forecasts": len(omitted_targets),
            "with_scored_observations": sum(t["scored_observation_count"] > 0 for t in fixed_targets),
            "missing_observations": sum(t["measurement_state"] == "missing_observation"
                                        for t in fixed_targets),
            "received_unscorable": sum(t["measurement_state"] == "received_unscorable"
                                       for t in fixed_targets),
        },
        "forecast_abstentions": [{"specimen_id": sid, "quantity": q}
                                 for sid, q in sorted(targets)
                                 if (sid, q) not in omitted_targets
                                 and forecasts[sid][q].get("mean") is None],
        "omitted_forecasts": [{"specimen_id": sid, "quantity": q}
                              for sid, q in sorted(omitted_targets)],
        "excluded": excluded,
        "missing_measurements": [{"specimen_id": sid, "quantity": q}
                                 for sid, q in sorted(targets - received_targets)],
        "unscorable_measurements": unscorable,
        "stage_unassessable": [row for row in stage_checks if row["status"] == "not_assessable"],
        "timing": temporal,
        "genealogy": {q: _genealogy([r for r in accepted if r["quantity"] == q])
                      for q in sorted(wanted)},
        "history_conflicts": history_conflicts,
        "reported_genealogy_changes": genealogy_changes,
        "quality_status_not_recorded": [r["evidence_id"] for r in accepted
                                        if r.get("status") is None],
        "limits": [
            "The caller must authenticate immutable forecast bytes and their evidence cutoff",
            "Later receipt/release does not prove physical execution occurred after prediction",
            "Unknown timing or genealogy is not a pass, failure, or independent replicate",
            "Matched fields are descriptive residuals, not independent manufacture",
            "Missing means no matching supplied observation record, not proof no measurement occurred",
            "Absent records, received unscorable observations and forecast abstentions remain separate",
            "Only explicit compatible stages can score physical measurements; unknown is not failure",
            "No aggregate success score, scientific certification, or training eligibility",
        ],
    }


def evaluate_campaign_request(request_record, observations, *, quantities=NUMERICAL_QUANTITIES,
                              allow_omitted_forecasts=False):
    """Public scoring route with full eligibility and legacy top-level diagnostics.

    The immutable request fixes target membership before outcomes. A caller may
    predeclare a quantity subset, but must not select it after inspecting outcomes.
    This verifies supplied record consistency, not authenticity or scientific merit.
    Study-only allow_omitted_forecasts preserves absent outputs as omissions, never
    converts them into justified abstentions, and retains every requested target.
    """
    report = evaluate_fresh_predictions(request_record, observations, quantities=quantities,
                                       allow_omitted_forecasts=allow_omitted_forecasts)
    return {**report["diagnostics"], **report}


def check_support(prediction, *, expected="either", required_metadata=()):
    """Check a selected quantity output against a predeclared support expectation.

    The caller selects the quantity item from any executed model's output. A numeric
    prediction is not proven physically right; an abstention is not inherently good.
    """
    if expected not in {"numeric", "abstain", "either"}:
        raise ValueError("expected must be numeric, abstain or either")
    violations = []
    for key in ("mean", "sd", "unit", "status"):
        if key not in prediction:
            violations.append(f"missing_{key}")
    value, sd = prediction.get("mean"), prediction.get("sd")
    for key, number in (("mean", value), ("sd", sd)):
        if number is not None:
            try:
                finite(number, key, nonnegative=key == "sd")
            except (ValueError, TypeError):
                violations.append(f"invalid_{key}")
    if not isinstance(prediction.get("unit"), str) or not prediction["unit"]:
        violations.append("missing_unit_description")
    if not isinstance(prediction.get("status"), str) or not prediction["status"]:
        violations.append("missing_support_status")
    if value is None:
        if sd is not None:
            violations.append("uncertainty_without_mean")
        if not prediction.get("reason") and not prediction.get("scope"):
            violations.append("unexplained_abstention")
    elif prediction.get("status") in ABSTENTION_STATUSES:
        violations.append("numeric_value_with_abstention_status")
    if expected == "numeric" and value is None:
        violations.append("answerable_case_abstained")
    if expected == "abstain" and value is not None:
        violations.append("unsupported_case_predicted")
    for key in required_metadata:
        if prediction.get(key) is None:
            violations.append(f"missing_metadata:{key}")
    return {"check": "support", "expected": expected, "satisfied": not violations,
            "violations": violations, "scientific_correctness_verified": False}


def _equivalent(left, right, tolerance):
    if type(left) in (int, float) and type(right) in (int, float):
        return math.isclose(left, right, rel_tol=0, abs_tol=tolerance)
    return left == right


def compare_probe_outputs(
    reference, changed, *, probe_kind, expected="observe", fields=("mean", "sd"), tolerance=0.0
):
    """Assess already executed output pairs; never execute or repair an investigator.

    Input/source hashes, the single changed factor and scientific justification of
    the expectation belong in the caller's probe receipt. Invariance can be correct
    for descriptive scatter; independence-based precision may require abstention or
    a declared clustered model. Widening alone does not validate that model.
    """
    if probe_kind not in {"quality", "genealogy", "support", "retention", "numerical"}:
        raise ValueError("unknown probe_kind")
    if expected not in {"observe", "invariant", "abstain_mean", "abstain_uncertainty",
                        "widen_uncertainty"}:
        raise ValueError("unknown probe expectation")
    tolerance = finite(tolerance, "comparison tolerance", nonnegative=True)
    differences = {}
    for field in fields:
        if field not in reference or field not in changed:
            raise ValueError(f"comparison field missing: {field}")
        if not _equivalent(reference[field], changed[field], tolerance):
            differences[field] = {"reference": copy.deepcopy(reference[field]),
                                  "changed": copy.deepcopy(changed[field])}
    support = [check_support(item) for item in (reference, changed)]
    valid = all(item["satisfied"] for item in support)
    satisfied = None
    if expected == "invariant":
        satisfied = valid and not differences
    elif expected == "abstain_mean":
        satisfied = valid and changed.get("mean") is None
    elif expected == "abstain_uncertainty":
        satisfied = valid and changed.get("sd") is None
    elif expected == "widen_uncertainty":
        satisfied = (valid and reference.get("sd") is not None and changed.get("sd") is not None
                     and float(changed["sd"]) > float(reference["sd"]) + tolerance)
    return {"check": probe_kind, "expected": expected, "satisfied": satisfied,
            "differences": differences, "output_contract_checks": support,
            "scientific_correctness_verified": False,
            "limit": "Only the declared response constraint was tested; no physical outcome implied"}


def audit_claim(record, *, available_refs):
    """Validate an evidence-linked human/reviewer assessment, not the truth of prose.

    All reference IDs must resolve in the caller's public audit inventory. Their
    content, causal relevance and evaluator independence require separate review.
    The claim text is retained verbatim and is never classified by lexical rules.
    """
    for key in ("claim_id", "claim", "reviewer", "rationale", "scope", "evidence_cutoff",
                "optimized_signal", "required_function"):
        _identifier(record.get(key), key)
    if record.get("axis") not in AXES:
        raise ValueError("unknown evaluation axis")
    if record.get("assessment") not in {
        "supported", "qualified", "unsupported", "contradicted", "not_assessable"
    }:
        raise ValueError("unknown claim assessment")
    if record.get("function_bridge") not in {"measured", "conditional", "unmeasured",
                                             "not_applicable"}:
        raise ValueError("unknown function_bridge status")
    limitations = record.get("limitations")
    if not isinstance(limitations, list) or any(not isinstance(x, str) or not x for x in limitations):
        raise ValueError("limitations must be an explicit list of descriptions")
    refs = record.get("references")
    if not isinstance(refs, dict) or set(refs) != REFERENCE_ROLES:
        raise ValueError("references must explicitly include every reference role")
    inventory = set(available_refs)
    for role, ids in refs.items():
        if not isinstance(ids, list) or any(not isinstance(x, str) or not x for x in ids):
            raise ValueError(f"invalid references for {role}")
        if len(set(ids)) != len(ids) or not set(ids) <= inventory:
            raise ValueError(f"duplicate or unresolved references for {role}")
    warnings = []
    if not refs["independent_result"]:
        warnings.append("No independent-result reference; fresh support has not been established")
    if record["function_bridge"] in {"unmeasured", "conditional"}:
        warnings.append("Optimized signal does not establish required physical function")
    if record["assessment"] == "supported" and not any(refs.values()):
        warnings.append("Supported assessment has no referenced evidence; reviewer must resolve it")
    return {"schema_version": 1, "record_valid": True, "record": copy.deepcopy(record),
            "warnings": warnings, "scientific_support_verified": False,
            "training_eligible": False}
